import Link from "next/link";
export default async function OrderPage({params}:{params:Promise<{id:string}>}){const {id}=await params;return <main className="section-shell py-14 md:py-20"><div className="kicker">Live order</div><h1 className="mt-3 font-serif text-5xl">#{id}</h1><p className="mt-3 text-[#9b958c]">Frontend demo status timeline.</p><div className="mt-10 grid gap-4 md:grid-cols-5">{["Confirmed","Preparing","Ready","Out for delivery","Delivered"].map((x,i)=><div key={x} className="card p-5"><div className={`h-2 w-2 rounded-full ${i<4?"bg-[#d9a35f]":"bg-white/20"}`}/><div className="mt-4 font-semibold">{x}</div><div className="mt-2 text-xs text-[#827b72]">{i===3?"Courier is on the way":"Completed"}</div></div>)}</div><div className="mt-8 card p-7"><div className="kicker">Delivery</div><div className="mt-4 grid gap-2 text-sm text-[#b0aaa0]"><div>Cadjèhoun → Fidjrossè</div><div>Courier: Armand S. · +229 90 44 18 20</div><div>ETA: 18 minutes</div></div><Link href="/delivery" className="btn btn-ghost mt-6">Open delivery console</Link></div></main>}
